{
  "identity": {
    "name": "Idaho PC Solutions, LLC",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "The company operates under the legal name Idaho PC Solutions, LLC in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "This policy explains how Idaho PC Solutions, LLC handles information collected through this website, service requests, customer communications, repair and IT services, and payments."
      },
      {
        "statement": "The business operates a physical office located at 280 N 8th St in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html",
        "quote": "Visit by appointment 280 N 8th St Boise, ID 83702 Monday–Friday: 10 a.m.–6 p.m."
      }
    ]
  },
  "industry": {
    "industry": "Computer Repair and Information Technology (IT) Support",
    "activities": [
      "Desktop and laptop computer diagnostics and repairs",
      "Business IT and managed workstation support",
      "Network, cabling, and Wi-Fi setup",
      "Malware removal and security cleanups",
      "Data backup, transfer, and file recovery",
      "Cloud services and Microsoft 365 configuration"
    ],
    "claims": [
      {
        "statement": "The business provides computer repair and business IT support to Boise and the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": "Computer repair and business IT support for Boise and the Treasure Valley."
      },
      {
        "statement": "The company operates in computer hardware and IT services rather than mechanical home contracting trades such as HVAC, plumbing, or electrical.",
        "label": "inference",
        "sourceUrl": "https://www.idahopcsolutions.com/services.html",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.idahopcsolutions.com/",
    "claims": [
      {
        "statement": "The business was established in 2007.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "Founded in 2007, Idaho PC Solutions has spent nearly two decades helping homeowners and small businesses with straightforward advice and practical technology solutions."
      },
      {
        "statement": "Services are delivered by appointment at their Boise location, on-site, or remotely across the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "Our Boise location is available by appointment. We also serve the Treasure Valley with on-site and remote support where appropriate."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The business entity is identified in legal policies as a limited liability company, Idaho PC Solutions, LLC.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "This policy explains how Idaho PC Solutions, LLC handles information collected through this website, service requests, customer communications, repair and IT services, and payments."
      },
      {
        "statement": "The website displays no trade contractor licensing or state construction registration numbers.",
        "label": "inference",
        "sourceUrl": "https://www.idahopcsolutions.com/blank-page.html",
        "quote": null
      }
    ],
    "limitations": "The website does not display state corporate registry numbers or professional IT vendor certifications; residential specialty trade contractor licenses do not apply to IT and computer repair operations."
  },
  "existingSoftware": [
    {
      "product": "Wix",
      "purpose": "Website hosting, headless scripts, and customer intake forms",
      "evidence": {
        "statement": "Wix hosts the website and provides customer inquiry form processing services.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "Information may be shared with service providers supporting website hosting and forms (including Wix), communications, payment processing, and authorized repair or IT work"
      }
    },
    {
      "product": "Authorize.net",
      "purpose": "Payment gateway for processing customer transactions and invoicing",
      "evidence": {
        "statement": "Customer payments and card transactions are processed via Authorize.net.",
        "label": "fact",
        "sourceUrl": "https://www.idahopcsolutions.com/privacy-policy.html",
        "quote": "When a payment is processed through Authorize.net, information needed for that transaction is provided to Authorize.net and the financial institutions or processors involved."
      }
    },
    {
      "product": "Floot (Service Desk)",
      "purpose": "Internal staff service desk application referenced via site assets",
      "evidence": {
        "statement": "The site references an external service desk domain hosted on floot.app.",
        "label": "inference",
        "sourceUrl": "https://www.idahopcsolutions.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company accepts service inquiries via phone calls, text messages, standard email, and an embedded web form.",
      "label": "fact",
      "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html",
      "quote": "CALL [redacted] ↗ Talk through the problem and schedule service. TEXT Send a message ↗ Include the device, symptoms, and your location. EMAIL [redacted]"
    },
    {
      "statement": "Because the company provides bench and on-site IT support rather than trade-contractor field services, residential contractor lead-to-job automations are not applicable.",
      "label": "inference",
      "sourceUrl": "https://www.idahopcsolutions.com/services.html",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Handling unintegrated inbound communication channels manually across calls, texts, emails, and forms.",
      "label": "hypothesis",
      "basis": "Inbound inquiries are received through direct phone, text, an @gmail.com address, and an embedded Wix form, which can create administrative drag for an owner-technician if not centrally aggregated."
    },
    {
      "problem": "Incompatibility with ForgeX's home-service trade contractor automation packages.",
      "label": "inference",
      "basis": "The business operates in consumer and small business computer support, lacking the field dispatch and paid residential trade lead pipelines that ForgeX's solutions serve."
    }
  ],
  "existingSolutions": [
    {
      "solution": "IT Service Desk & Ticketing Software (e.g., floot.app reference or dedicated PSA/RMM systems)",
      "addresses": "Managing customer repair queues, device status tracking, and technician notes.",
      "alreadyOwned": true
    },
    {
      "solution": "Wix Forms & Authorize.net Billing",
      "addresses": "Inbound intake requests and credit card processing for diagnostics and labor.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "Idaho PC Solutions, LLC is not in ForgeX's target market of trade contractors (HVAC, plumbing, electrical). Implementing contractor-focused automation is not technically or commercially appropriate."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX catalog or custom solutions are recommended because the company falls outside ForgeX's target business segment."
  },
  "humanReview": [
    "Owner verification of technical repair scoping, parts ordering, and diagnostics.",
    "Manual inspection of customer backups and data recovery transfers before hardware handoff."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Engaging businesses outside ForgeX's target segment squanders sales and development capacity on non-contractor workflows."
    },
    {
      "type": "security",
      "description": "IT repair businesses manage sensitive customer credentials, operating system access, and data recovery files that require strict confidentiality controls."
    },
    {
      "type": "compliance",
      "description": "Outreach must adhere to CAN-SPAM regulations and avoid irrelevant marketing communications."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "Managing Member"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Owner & IT technician",
        "sourceUrl": "https://www.idahopcsolutions.com/about-us.html",
        "quote": "[redacted] Owner & IT technician"
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html"
      },
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html"
      },
      {
        "kind": "web form",
        "value": "https://vbzlife1.wixforms.com/f/7508933512351712280",
        "sourceUrl": "https://www.idahopcsolutions.com/contact-us.html"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How do you currently triage incoming calls, texts, and emails into your service desk workflow?",
      "Does your current floot.app portal handle automatic customer repair notifications, or is that managed manually?",
      "Are you looking to expand commercial managed IT contracts, or does your primary focus remain bench and local on-site repairs?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.idahopcsolutions.com/",
        "usedFor": "Company overview, service categories, pricing highlights, and footer contact details"
      },
      {
        "url": "https://www.idahopcsolutions.com/about-us.html",
        "usedFor": "Owner identity ([redacted]), founding year (2007), and appointment-based business model"
      },
      {
        "url": "https://www.idahopcsolutions.com/contact-us.html",
        "usedFor": "Operating hours, street address, direct contact channels, and Wix form embed link"
      },
      {
        "url": "https://www.idahopcsolutions.com/computer-repair-it-pricing.html",
        "usedFor": "Diagnostic, remote, on-site, and malware removal service rates"
      },
      {
        "url": "https://www.idahopcsolutions.com/blank-page.html",
        "usedFor": "Terms and conditions, device warranty rules, and legal entity references"
      },
      {
        "url": "https://www.idahopcsolutions.com/privacy-policy.html",
        "usedFor": "Legal business entity verification and software disclosures (Wix, Authorize.net)"
      },
      {
        "url": "https://www.idahopcsolutions.com/services.html",
        "usedFor": "Verification of IT, computer repair, and network support service lines"
      }
    ],
    "limitations": [
      "The website does not state exact team headcount, though presentation indicates an owner-operated shop with one primary technician.",
      "Advertising expenditure, lead volume, and state business registration records are not disclosed on the website."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Idaho PC Solutions, LLC is a local computer repair and small business IT provider led by owner-technician [redacted]. ForgeX's target segment consists specifically of owner-led home-service trade contractors (HVAC, plumbing, and electrical) with approximately 10 to 75 staff who purchase residential leads. Because this company operates in consumer/commercial IT services rather than the mechanical trades and appears to be a solo or small IT bench operation, it falls outside ForgeX's segment."
  }
}
